package com.taskmate.ui.auth;
import com.formdev.flatlaf.FlatLightLaf;import com.taskmate.dao.AuthDao;import com.taskmate.models.User;import com.taskmate.ui.components.DashboardFrame;import javax.swing.*;import java.awt.*;
public class LoginFrame extends JFrame {
 private final JTextField email=new JTextField(24);private final JPasswordField password=new JPasswordField(24);
 public LoginFrame(){super("TaskMate | Sign in");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(470,390);setLocationRelativeTo(null);JPanel root=new JPanel(new GridBagLayout());root.setBackground(new Color(245,249,247));JPanel card=new JPanel(new GridBagLayout());card.setBorder(BorderFactory.createEmptyBorder(28,34,28,34));card.setBackground(Color.WHITE);GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,5,8,5);g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("TaskMate");title.setFont(title.getFont().deriveFont(Font.BOLD,30f));title.setForeground(new Color(20,77,57));card.add(title,g);g.gridy++;JLabel sub=new JLabel("Academic task and assessment management");card.add(sub,g);g.gridwidth=1;g.gridy++;g.gridx=0;card.add(new JLabel("Email"),g);g.gridx=1;card.add(email,g);g.gridy++;g.gridx=0;card.add(new JLabel("Password"),g);g.gridx=1;card.add(password,g);g.gridy++;g.gridx=0;g.gridwidth=2;JButton login=new JButton("Sign in");login.addActionListener(e->signIn());card.add(login,g);root.add(card);setContentPane(root);getRootPane().setDefaultButton(login);}
 private void signIn(){char[] p=password.getPassword();try{var result=new AuthDao().login(email.getText(),p);if(result.isEmpty()){JOptionPane.showMessageDialog(this,"Email or password is incorrect, or the account is inactive.","Sign in failed",JOptionPane.ERROR_MESSAGE);return;}dispose();new DashboardFrame(result.get()).setVisible(true);}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Cannot sign in",JOptionPane.ERROR_MESSAGE);}finally{java.util.Arrays.fill(p,'\0');password.setText("");}}
 public static void launch(){FlatLightLaf.setup();SwingUtilities.invokeLater(()->new LoginFrame().setVisible(true));}
}
